441	  public reply(
442	    response: TRawResponse | TReply,
443	    body: any,
444	    statusCode?: number,
445	  ) {
446	    const fastifyReply: TReply = this.isNativeResponse(response)
447	      ? new Reply(
448	          response,
449	          {
450	            [kRouteContext]: {
451	              preSerialization: null,
452	              preValidation: [],
453	              preHandler: [],
454	              onSend: [],
455	              onError: [],
456	            },
457	          },
458	          {},
459	        )
460	      : response;
461	
462	    if (!isNil(statusCode)) {
463	      fastifyReply.status(statusCode);
464	    }
465	    if (body instanceof StreamableFile) {
466	      const streamHeaders = body.getHeaders();
467	      if (
468	        fastifyReply.getHeader('Content-Type') === undefined &&
469	        streamHeaders.type !== undefined
470	      ) {
471	        fastifyReply.header('Content-Type', streamHeaders.type);
472	      }
473	      if (
474	        fastifyReply.getHeader('Content-Disposition') === undefined &&
475	        streamHeaders.disposition !== undefined
476	      ) {
477	        fastifyReply.header('Content-Disposition', streamHeaders.disposition);
478	      }
479	      if (
480	        fastifyReply.getHeader('Content-Length') === undefined &&
481	        streamHeaders.length !== undefined
482	      ) {
483	        fastifyReply.header('Content-Length', streamHeaders.length);
484	      }
485	      body = body.getStream();
486	    }
487	    if (
488	      fastifyReply.getHeader('Content-Type') !== undefined &&
489	      fastifyReply.getHeader('Content-Type') !== 'application/json' &&
490	      body?.statusCode >= HttpStatus.BAD_REQUEST
491	    ) {
492	      Logger.warn(
493	        "Content-Type doesn't match Reply body, you might need a custom ExceptionFilter for non-JSON responses",
494	        FastifyAdapter.name,
495	      );
496	      fastifyReply.header('Content-Type', 'application/json');
497	    }
498	    return fastifyReply.send(body);
499	  }
