704	  public async createMiddlewareFactory(
705	    requestMethod: RequestMethod,
706	  ): Promise<(path: string, callback: Function) => any> {
707	    if (!this.isMiddieRegistered) {
708	      await this.registerMiddie();
709	    }
710	    return (path: string, callback: Function) => {
711	      const hasEndOfStringCharacter = path.endsWith('$');
712	      path = hasEndOfStringCharacter ? path.slice(0, -1) : path;
713	
714	      let normalizedPath = LegacyRouteConverter.tryConvert(path);
715	
716	      // Fallback to "*path" to support plugins like GraphQL
717	      normalizedPath = normalizedPath === '/*path' ? '*path' : normalizedPath;
718	
719	      // Normalize the path to support the prefix if it set in application
720	      if (
721	        this._pathPrefix &&
722	        !normalizedPath.startsWith(this._pathPrefix) &&
723	        (normalizedPath === '/' || normalizedPath === '')
724	      ) {
725	        normalizedPath = `${this._pathPrefix}${normalizedPath}`;
726	        if (normalizedPath.endsWith('/')) {
727	          normalizedPath = `${normalizedPath}{*path}`;
728	        }
729	      }
730	
731	      try {
732	        let { regexp: re } = pathToRegexp(normalizedPath);
733	        re = hasEndOfStringCharacter
734	          ? new RegExp(re.source + '$', re.flags)
735	          : re;
736	
737	        // The following type assertion is valid as we use import('@fastify/middie') rather than require('@fastify/middie')
738	        // ref https://github.com/fastify/middie/pull/55
739	        this.instance.use(
740	          normalizedPath,
741	          (req: any, res: any, next: Function) => {
742	            const queryParamsIndex = req.originalUrl.indexOf('?');
743	            let pathname =
744	              queryParamsIndex >= 0
745	                ? req.originalUrl.slice(0, queryParamsIndex)
746	                : req.originalUrl;
747	
748	            pathname = this.sanitizeUrl(pathname);
749	
750	            if (normalizedPath) {
751	              const pathToCheck = pathname.endsWith('/')
752	                ? pathname
753	                : `${pathname}/`;
754	              if (!re.exec(pathToCheck)) {
755	                return next();
756	              }
757	            }
758	            return callback(req, res, next);
759	          },
760	        );
761	      } catch (e) {
762	        if (e instanceof TypeError) {
763	          LegacyRouteConverter.printError(path);
764	        }
765	        throw e;
766	      }
767	    };
768	  }
