871	  private injectRouteOptions(
872	    routerMethodKey: Uppercase<HTTPMethods>,
873	    ...args: any[]
874	  ) {
875	    const handlerRef = args[args.length - 1];
876	    const isVersioned =
877	      !isUndefined(handlerRef.version) &&
878	      handlerRef.version !== VERSION_NEUTRAL;
879	    const routeConfig = Reflect.getMetadata(
880	      FASTIFY_ROUTE_CONFIG_METADATA,
881	      handlerRef,
882	    );
883	
884	    const routeConstraints = Reflect.getMetadata(
885	      FASTIFY_ROUTE_CONSTRAINTS_METADATA,
886	      handlerRef,
887	    );
888	
889	    const routeSchema = Reflect.getMetadata(
890	      FASTIFY_ROUTE_SCHEMA_METADATA,
891	      handlerRef,
892	    );
893	
894	    const hasConfig = !isUndefined(routeConfig);
895	    const hasConstraints = !isUndefined(routeConstraints);
896	    const hasSchema = !isUndefined(routeSchema);
897	    const routeToInject: RouteOptions<TServer, TRawRequest, TRawResponse> &
898	      RouteShorthandOptions = {
899	      method: routerMethodKey,
900	      url: args[0],
901	      handler: handlerRef,
902	    };
903	
904	    if (!this.instance.supportedMethods.includes(routerMethodKey)) {
905	      this.instance.addHttpMethod(routerMethodKey, { hasBody: true });
906	    }
907	
908	    if (isVersioned || hasConstraints || hasConfig || hasSchema) {
909	      const isPathAndRouteTuple = args.length === 2;
910	      if (isPathAndRouteTuple) {
911	        const constraints = {
912	          ...(hasConstraints && routeConstraints),
913	          ...(isVersioned && {
914	            version: handlerRef.version,
915	          }),
916	        };
917	
918	        const options = {
919	          constraints,
920	          ...(hasConfig && {
921	            config: {
922	              ...routeConfig,
923	            },
924	          }),
925	          ...(hasSchema && {
926	            schema: routeSchema,
927	          }),
928	        };
929	
930	        const routeToInjectWithOptions = { ...routeToInject, ...options };
931	
932	        return this.instance.route(routeToInjectWithOptions);
933	      }
934	    }
935	    return this.instance.route(routeToInject);
936	  }
