967	  private sanitizeUrl(url: string): string {
968	    const initialConfig = this.instance.initialConfig as FastifyServerOptions;
969	    const routerOptions =
970	      initialConfig.routerOptions as Partial<FastifyServerOptions>;
971	
972	    // Absolute-form request targets ("GET http://host/path HTTP/1.1") must be
973	    // resolved to their path before any other normalization, as the Fastify
974	    // router does, so that middleware and routes always match the same path.
975	    url = this.getPathFromRequestTarget(url);
976	
977	    if (
978	      routerOptions.ignoreDuplicateSlashes ||
979	      initialConfig.ignoreDuplicateSlashes
980	    ) {
981	      url = this.removeDuplicateSlashes(url);
982	    }
983	
984	    if (
985	      routerOptions.ignoreTrailingSlash ||
986	      initialConfig.ignoreTrailingSlash
987	    ) {
988	      url = this.trimLastSlash(url);
989	    }
990	
991	    if (
992	      routerOptions.caseSensitive === false ||
993	      initialConfig.caseSensitive === false
994	    ) {
995	      url = url.toLowerCase();
996	    }
997	    return safeDecodeURI(
998	      url,
999	      routerOptions.useSemicolonDelimiter ||
1000	        initialConfig.useSemicolonDelimiter,
1001	    ).path;
1002	  }
1003	
1004	  private removeDuplicateSlashes(path: string) {
1005	    const REMOVE_DUPLICATE_SLASHES_REGEXP = /\/\/+/g;
1006	    return path.indexOf('//') !== -1
1007	      ? path.replace(REMOVE_DUPLICATE_SLASHES_REGEXP, '/')
1008	      : path;
1009	  }
1010	
1011	  private trimLastSlash(path: string) {
1012	    if (path.length > 1 && path.charCodeAt(path.length - 1) === 47) {
1013	      return path.slice(0, -1);
1014	    }
1015	    return path;
1016	  }
