1018	  /**
1019	   * Mirrors the absolute-form request target handling of "find-my-way".
1020	   * Returns the path of an absolute-form target ("http://host/path" -> "/path")
1021	   * and leaves any other request target untouched.
1022	   */
1023	  private getPathFromRequestTarget(url: string): string {
1024	    if (url.charCodeAt(0) === 47 /* '/' */) {
1025	      return url;
1026	    }
1027	    const schemeEnd = url.indexOf('://');
1028	    if (schemeEnd === -1) {
1029	      return url;
1030	    }
1031	    const scheme = url.slice(0, schemeEnd).toLowerCase();
1032	    if (scheme !== 'http' && scheme !== 'https') {
1033	      return url;
1034	    }
1035	    const authorityStart = schemeEnd + 3;
1036	    const pathStart = url.indexOf('/', authorityStart);
1037	    if (pathStart === authorityStart || !URL.canParse(url)) {
1038	      // Malformed target: the router rejects it before any middleware runs
1039	      return url;
1040	    }
1041	    return pathStart === -1 ? '/' : url.slice(pathStart);
