48	export class NestApplication
49	  extends NestApplicationContext<NestApplicationOptions>
50	  implements INestApplication
51	{
52	  protected readonly logger = new Logger(NestApplication.name, {
53	    timestamp: true,
54	  });
55	  private readonly middlewareModule: MiddlewareModule;
56	  private readonly middlewareContainer = new MiddlewareContainer(
57	    this.container,
58	  );
59	  private microservicesModule: any = null;
60	  private socketModule: any = null;
61	  private readonly routesResolver: Resolver;
62	  private readonly microservices: any[] = [];
63	  private httpServer: any;
64	  private isListening = false;
65	  private isWsModuleRegistered = false;
66	
67	  constructor(
68	    container: NestContainer,
69	    private readonly httpAdapter: HttpServer,
70	    private readonly config: ApplicationConfig,
71	    private readonly graphInspector: GraphInspector,
72	    appOptions: NestApplicationOptions = {},
73	  ) {
74	    super(container, appOptions);
75	
76	    this.config.setRouteConflictPolicy(appOptions.routeConflictPolicy);
77	    this.config.setRouteResolutionStrategy(appOptions.routeResolutionStrategy);
78	    this.selectContextModule();
79	    this.registerHttpServer();
80	    this.injector = new Injector({
81	      preview: this.appOptions.preview!,
82	      instanceDecorator: appOptions.instrument?.instanceDecorator,
83	    });
84	    this.middlewareModule = new MiddlewareModule();
85	    this.routesResolver = new RoutesResolver(
86	      this.container,
87	      this.config,
88	      this.injector,
89	      this.graphInspector,
90	    );
91	  }
92	
93	  protected async prepareClose(): Promise<void> {
94	    this.httpAdapter && (await this.httpAdapter.beforeClose?.());
95	  }
96	
97	  protected async dispose(): Promise<void> {
98	    await this.socketModule?.close();
99	    await this.microservicesModule?.close();
100	    await this.httpAdapter?.close();
101	
102	    await Promise.all(
103	      iterate(this.microservices).map(async microservice => {
104	        microservice.setIsTerminated(true);
105	        await microservice.close();
106	      }),
107	    );
108	  }
109	
110	  public getHttpAdapter(): AbstractHttpAdapter {
111	    return this.httpAdapter as AbstractHttpAdapter;
112	  }
113	
114	  public registerHttpServer() {
115	    this.httpServer = this.createServer();
116	  }
117	
118	  public getUnderlyingHttpServer<T>(): T {
119	    return this.httpAdapter.getHttpServer();
120	  }
121	
122	  public applyOptions() {
123	    if (!this.appOptions || !this.appOptions.cors) {
124	      return undefined;
125	    }
126	    const passCustomOptions =
127	      isObject(this.appOptions.cors) || isFunction(this.appOptions.cors);
128	    if (!passCustomOptions) {
129	      return this.enableCors();
130	    }
131	    return this.enableCors(this.appOptions.cors);
132	  }
133	
134	  public createServer<T = any>(): T {
135	    this.httpAdapter.initHttpServer(this.appOptions);
136	    return this.httpAdapter.getHttpServer() as T;
137	  }
138	
139	  public async registerModules() {
140	    await this.registerWsModule();
141	
142	    if (this.microservicesModule) {
143	      this.microservicesModule.register(
144	        this.container,
145	        this.graphInspector,
146	        this.config,
147	        this.appOptions,
148	      );
149	      this.microservicesModule.setupClients(this.container);
150	    }
151	
152	    await this.middlewareModule.register(
153	      this.middlewareContainer,
154	      this.container,
155	      this.config,
156	      this.injector,
157	      this.httpAdapter,
158	      this.graphInspector,
159	      this.appOptions,
160	    );
161	  }
162	
163	  public async registerWsModule() {
164	    if (!this.socketModule) {
165	      return;
166	    }
167	    await this.socketModule.register(
168	      this.container,
169	      this.config,
170	      this.graphInspector,
171	      this.appOptions,
172	      this.httpServer,
173	    );
174	    this.isWsModuleRegistered = true;
175	  }
176	
177	  public async init(): Promise<this> {
178	    if (this.isInitialized) {
179	      return this;
180	    }
181	
182	    // Lazy-load optional modules (ESM-compatible)
183	    await Promise.all([
184	      this.loadSocketModule(),
185	      this.loadMicroservicesModule(),
186	    ]);
187	    this.applyOptions();
188	    await this.httpAdapter?.init?.();
189	
190	    const useBodyParser =
191	      this.appOptions && this.appOptions.bodyParser !== false;
192	    useBodyParser && this.registerParserMiddleware();
193	
194	    await this.registerModules();
195	    await this.registerRouter();
196	    await this.callInitHook();
197	    await this.registerRouterHooks();
198	    await this.callBootstrapHook();
199	
200	    this.isInitialized = true;
201	    this.logger.log(MESSAGES.APPLICATION_READY);
202	    return this;
203	  }
204	
205	  public registerParserMiddleware() {
206	    const prefix = this.config.getGlobalPrefix();
207	    const rawBody = !!this.appOptions?.rawBody;
208	    this.httpAdapter.registerParserMiddleware(prefix, rawBody);
209	  }
210	
211	  public async registerRouter() {
212	    await this.registerMiddleware(this.httpAdapter);
213	
214	    const prefix = this.config.getGlobalPrefix();
215	    const basePath = addLeadingSlash(prefix);
216	
217	    const conflictPolicy = this.config.getRouteConflictPolicy();
218	    const resolutionStrategy = this.config.getRouteResolutionStrategy();
219	    const adapterIsOrderSensitive =
220	      this.httpAdapter.isRouteOrderSensitive?.() ?? true;
221	    const shouldSortBySpecificity =
222	      resolutionStrategy === 'specificity' && adapterIsOrderSensitive;
223	    // Adapters that are not order-sensitive (e.g. Fastify) currently
224	    // also reject duplicate (method, URL) registrations synchronously
225	    // from the underlying router. Treat the two properties as one
226	    // signal until a separate capability flag is introduced.
227	    const adapterRejectsDuplicates = !adapterIsOrderSensitive;
228	
229	    if (!conflictPolicy && !shouldSortBySpecificity) {
230	      this.routesResolver.resolve(this.httpAdapter, basePath);
231	      return;
232	    }
233	
234	    // Defer registration whenever we collect routes for diagnostics or
235	    // re-ordering. In particular, when a conflict policy is set we
236	    // must run detection *before* the adapter sees any route, because
237	    // duplicate-rejecting adapters like Fastify throw synchronously
238	    // from `instance.route()` and would short-circuit both the resolve
239	    // loop and the aggregated `RouteConflictException`.
240	    const resolvedRoutes: ResolvedRoute[] = [];
241	    this.routesResolver.resolve(this.httpAdapter, basePath, {
242	      onRouteResolved: route => resolvedRoutes.push(route),
243	      deferRegistration: true,
244	    });
245	
246	    // Sort before conflict detection so that winner/shadowed pairs in every
247	    // conflict record reflect actual adapter registration order. Without this,
248	    // the reported winner could be the declaration-first (less-specific) route
249	    // even though the sorted-first (more-specific) route is what really wins.
250	    const orderedRoutes = shouldSortBySpecificity
251	      ? RouteSpecificitySorter.sort(resolvedRoutes)
252	      : resolvedRoutes;
253	
254	    const routesToSkip = new Set<ResolvedRoute>();
255	    if (conflictPolicy) {
256	      const filteredPolicy = adapterIsOrderSensitive
257	        ? conflictPolicy
258	        : { duplicate: conflictPolicy.duplicate };
259	
260	      const conflicts = RouteConflictDetector.detect(
261	        orderedRoutes,
262	        this.config.getVersioning(),
263	      );
264	
265	      // On adapters that reject duplicate registrations the policy
266	      // cannot be honoured by simply logging — the adapter would
267	      // throw on the second `instance.route()` call. Drop the
268	      // shadowed route of every duplicate conflict so the detector
269	      // (not the adapter) decides which one wins. The detector
270	      // always picks the earlier-registered route as the winner.
271	      if (adapterRejectsDuplicates) {
272	        conflicts.forEach(conflict => {
273	          if (conflict.kind === 'duplicate') {
274	            routesToSkip.add(conflict.shadowed);
275	          }
276	        });
277	      }
278	
279	      // When specificity sorting is active, shadow conflicts where the sort
280	      // promoted the winner (declared later but more specific) are resolved
281	      // at runtime: the more-specific route is first-registered and handles
282	      // its requests, the less-specific route handles the rest. Filtering
283	      // these out prevents shadow: 'error' from aborting an app whose routes
284	      // work correctly after specificity ordering. Genuine shadows — where the
285	      // winner was already first in declaration order and the sort did not help
286	      // — are kept and still apply the configured policy.
287	      const effectiveConflicts = shouldSortBySpecificity
288	        ? RouteConflictDetector.filterSortResolvedShadows(
289	            conflicts,
290	            resolvedRoutes,
291	          )
292	        : conflicts;
293	
294	      RouteConflictDetector.handle(
295	        effectiveConflicts,
296	        filteredPolicy,
297	        this.logger,
298	      );
299	    }
300	
301	    orderedRoutes.forEach(route => {
302	      if (routesToSkip.has(route)) return;
303	      this.routesResolver.registerResolvedRoute(this.httpAdapter, route);
304	    });
305	  }
306	
307	  public async registerRouterHooks() {
308	    this.routesResolver.registerNotFoundHandler();
309	    this.routesResolver.registerExceptionHandler();
310	  }
311	
312	  public connectMicroservice<T extends object>(
313	    microserviceOptions: T,
314	    hybridAppOptions: NestHybridApplicationOptions = {},
315	  ): INestMicroservice {
316	    const { NestMicroservice } = loadPackageCached(
317	      '@nestjs/microservices',
318	      'NestFactory',
319	    );
320	    const { inheritAppConfig } = hybridAppOptions;
321	    const applicationConfig = inheritAppConfig
322	      ? this.config
323	      : new ApplicationConfig();
324	
325	    const instance = new NestMicroservice(
326	      this.container,
327	      microserviceOptions,
328	      this.graphInspector,
329	      applicationConfig,
330	    );
331	
332	    if (!hybridAppOptions.deferInitialization) {
333	      instance.registerListeners();
334	      instance.setIsInitialized(true);
335	      instance.setIsInitHookCalled(true);
336	    }
337	
338	    this.microservices.push(instance);
339	    return instance;
340	  }
341	
342	  public getMicroservices(): INestMicroservice[] {
343	    return this.microservices;
344	  }
345	
346	  public getHttpServer() {
347	    return this.httpServer;
348	  }
349	
350	  public async startAllMicroservices(): Promise<this> {
351	    this.assertNotInPreviewMode('startAllMicroservices');
352	    await Promise.all(this.microservices.map(msvc => msvc.listen()));
353	    return this;
354	  }
355	
356	  public use(...args: [any, any?]): this {
357	    this.httpAdapter.use(...this.applyFunctionDecoratorIfRegistered(args));
358	    return this;
359	  }
360	
361	  public useBodyParser(...args: [any, any?]): this {
362	    if (!('useBodyParser' in this.httpAdapter)) {
363	      this.logger.warn('Your HTTP Adapter does not support `.useBodyParser`.');
364	      return this;
365	    }
366	
367	    const [parserType, ...otherArgs] = args;
368	    const rawBody = !!this.appOptions.rawBody;
369	
370	    this.httpAdapter.useBodyParser?.(...[parserType, rawBody, ...otherArgs]);
371	
372	    return this;
373	  }
374	
375	  public enableCors(options?: any): void {
376	    this.httpAdapter.enableCors(options);
377	  }
378	
379	  public enableVersioning(
380	    options: VersioningOptions = { type: VersioningType.URI },
381	  ): this {
382	    this.config.enableVersioning(options);
383	    return this;
384	  }
385	
386	  public async listen(port: number | string): Promise<any>;
387	  public async listen(port: number | string, hostname: string): Promise<any>;
388	  public async listen(port: number | string, ...args: any[]): Promise<any> {
389	    this.assertNotInPreviewMode('listen');
390	
391	    if (!this.isInitialized) {
392	      await this.init();
393	    }
394	
395	    const httpAdapterHost = this.container.getHttpAdapterHostRef();
396	    return new Promise((resolve, reject) => {
397	      const errorHandler = (e: any) => {
398	        this.logger.error(e?.toString?.());
399	        reject(e);
400	      };
401	      this.httpServer.once('error', errorHandler);
402	
403	      const isCallbackInOriginalArgs = isFunction(args[args.length - 1]);
404	      const listenFnArgs = isCallbackInOriginalArgs
405	        ? args.slice(0, args.length - 1)
406	        : args;
407	
408	      this.httpAdapter.listen(
409	        port,
410	        ...listenFnArgs,
411	        (...originalCallbackArgs: unknown[]) => {
412	          if (this.appOptions?.autoFlushLogs ?? true) {
413	            this.flushLogs();
414	          }
415	          if (originalCallbackArgs[0] instanceof Error) {
416	            return reject(originalCallbackArgs[0]);
417	          }
418	
419	          const address = this.httpServer.address();
420	          if (address) {
421	            this.httpServer.removeListener('error', errorHandler);
422	            this.isListening = true;
423	
424	            httpAdapterHost.listening = true;
425	            resolve(this.httpServer);
426	          }
427	          if (isCallbackInOriginalArgs) {
428	            args[args.length - 1](...originalCallbackArgs);
429	          }
430	        },
431	      );
432	    });
433	  }
434	
435	  public async getUrl(): Promise<string> {
436	    return new Promise((resolve, reject) => {
437	      if (!this.isListening) {
438	        this.logger.error(MESSAGES.CALL_LISTEN_FIRST);
439	        reject(MESSAGES.CALL_LISTEN_FIRST);
440	        return;
441	      }
442	      const address = this.httpServer.address();
443	      resolve(this.formatAddress(address));
444	    });
445	  }
446	
447	  private formatAddress(address: any): string {
448	    if (isString(address)) {
449	      if (platform() === 'win32') {
450	        return address;
451	      }
452	      const basePath = encodeURIComponent(address);
453	      return `${this.getProtocol()}+unix://${basePath}`;
454	    }
455	
456	    let host = this.host();
457	    if (address && address.family === 'IPv6') {
458	      if (host === '::') {
459	        host = '[::1]';
460	      } else {
461	        host = `[${host}]`;
462	      }
463	    } else if (host === '0.0.0.0') {
464	      host = '127.0.0.1';
465	    }
466	
467	    return `${this.getProtocol()}://${host}:${address.port}`;
468	  }
469	
470	  public setGlobalPrefix(prefix: string, options?: GlobalPrefixOptions): this {
471	    this.config.setGlobalPrefix(prefix);
472	    if (options) {
473	      const exclude = options?.exclude
474	        ? mapToExcludeRoute(options.exclude)
475	        : [];
476	      this.config.setGlobalPrefixOptions({
477	        ...options,
478	        exclude,
479	      });
480	    }
481	    return this;
482	  }
483	
484	  public useWebSocketAdapter(adapter: WebSocketAdapter): this {
485	    if (this.isWsModuleRegistered) {
486	      this.logger.warn(
487	        'useWebSocketAdapter() was called after WebSocket gateways were already initialized. The provided adapter will be stored but will NOT be applied to existing gateways — they remain bound to the previously installed adapter. To install a custom adapter, call app.useWebSocketAdapter(...) BEFORE app.init() (or app.listen()).',
488	      );
489	    }
490	    this.config.setIoAdapter(adapter);
491	    return this;
492	  }
493	
494	  public useGlobalFilters(...filters: ExceptionFilter[]): this {
495	    filters = this.applyInstanceDecoratorIfRegistered<ExceptionFilter>(
496	      ...filters,
497	    );
498	    this.config.useGlobalFilters(...filters);
499	    filters.forEach(item =>
500	      this.graphInspector.insertOrphanedEnhancer({
501	        subtype: 'filter',
502	        ref: item,
503	      }),
504	    );
505	    return this;
506	  }
507	
508	  public useGlobalPipes(...pipes: PipeTransform<any>[]): this {
509	    pipes = this.applyInstanceDecoratorIfRegistered<PipeTransform<any>>(
510	      ...pipes,
511	    );
512	    this.config.useGlobalPipes(...pipes);
513	    pipes.forEach(item =>
514	      this.graphInspector.insertOrphanedEnhancer({
515	        subtype: 'pipe',
516	        ref: item,
517	      }),
518	    );
519	    return this;
520	  }
521	
522	  public useGlobalInterceptors(...interceptors: NestInterceptor[]): this {
523	    interceptors = this.applyInstanceDecoratorIfRegistered<NestInterceptor>(
524	      ...interceptors,
525	    );
526	    this.config.useGlobalInterceptors(...interceptors);
527	    interceptors.forEach(item =>
528	      this.graphInspector.insertOrphanedEnhancer({
529	        subtype: 'interceptor',
530	        ref: item,
531	      }),
532	    );
533	    return this;
534	  }
535	
536	  public useGlobalGuards(...guards: CanActivate[]): this {
537	    guards = this.applyInstanceDecoratorIfRegistered<CanActivate>(...guards);
538	    this.config.useGlobalGuards(...guards);
539	    guards.forEach(item =>
540	      this.graphInspector.insertOrphanedEnhancer({
541	        subtype: 'guard',
542	        ref: item,
543	      }),
544	    );
545	    return this;
546	  }
547	
548	  public useStaticAssets(options: any): this;
549	  public useStaticAssets(path: string, options?: any): this;
550	  public useStaticAssets(pathOrOptions: any, options?: any): this {
551	    this.httpAdapter.useStaticAssets?.(pathOrOptions, options);
552	    return this;
553	  }
554	
555	  public setBaseViewsDir(path: string | string[]): this {
556	    this.httpAdapter.setBaseViewsDir?.(path);
557	    return this;
558	  }
559	
560	  public setViewEngine(engineOrOptions: any): this {
561	    this.httpAdapter.setViewEngine?.(engineOrOptions);
562	    return this;
563	  }
564	
565	  /**
566	   * Pre-load optional packages so that createNestApplication,
567	   * createNestMicroservice and createHttpAdapter can stay synchronous.
568	   */
569	  public async preloadLazyPackages(): Promise<void> {
570	    // Best-effort: silently swallow if packages are not installed
571	    await tryLoadPackage(
572	      '@nestjs/platform-express',
573	      () => import('@nestjs/platform-express'),
574	    );
575	    await tryLoadPackage(
576	      '@nestjs/microservices',
577	      () => import('@nestjs/microservices'),
578	    );
579	  }
580	
581	  private host(): string | undefined {
582	    const address = this.httpServer.address();
583	    if (isString(address)) {
584	      return undefined;
585	    }
586	    return address && address.address;
587	  }
588	
589	  private getProtocol(): 'http' | 'https' {
590	    return this.appOptions && this.appOptions.httpsOptions ? 'https' : 'http';
591	  }
592	
593	  private async registerMiddleware(instance: any) {
594	    await this.middlewareModule.registerMiddleware(
595	      this.middlewareContainer,
596	      instance,
597	    );
598	  }
599	
600	  private applyInstanceDecoratorIfRegistered<T>(...instances: T[]): T[] {
601	    if (this.appOptions.instrument?.instanceDecorator) {
602	      const decorate = makeSafeInstanceDecorator(
603	        this.appOptions.instrument.instanceDecorator,
604	      );
605	      return instances.map(instance => decorate(instance) as T);
606	    }
607	    return instances;
608	  }
609	
610	  private applyFunctionDecoratorIfRegistered(args: [any, any?]): [any, any?] {
611	    if (!this.appOptions.instrument?.instanceDecorator) {
612	      return args;
613	    }
614	    const decorate = makeSafeInstanceDecorator(
615	      this.appOptions.instrument.instanceDecorator,
616	    );
617	
618	    // Decorators may return a non-function value for plain middleware
619	    // functions; fall back to the original argument so the HTTP adapter
620	    // always receives a valid handler.
621	    const decorateFunction = (arg: any) => {
622	      if (!isFunction(arg)) {
623	        return arg;
624	      }
625	      const decorated = decorate(arg);
626	      return isFunction(decorated) ? decorated : arg;
627	    };
628	
629	    // Map over the original arguments to preserve arity: appending a trailing
630	    // `undefined` to a single-argument `use(fn)` call would make Express 5's
631	    // router throw "argument handler must be a function".
632	    return args.map(decorateFunction) as [any, any?];
633	  }
634	
635	  private async loadSocketModule() {
636	    if (!this.socketModule) {
637	      const socketModule = await optionalRequire(
638	        '@nestjs/websockets/socket-module',
639	        () => import('@nestjs/websockets/socket-module.js'),
640	      );
641	      if (socketModule?.SocketModule) {
642	        this.socketModule = new socketModule.SocketModule();
643	      }
644	    }
645	  }
646	
647	  private async loadMicroservicesModule() {
648	    if (!this.microservicesModule) {
649	      const msModule = await optionalRequire(
650	        '@nestjs/microservices/microservices-module',
651	        () => import('@nestjs/microservices/microservices-module.js'),
652	      );
653	      if (msModule?.MicroservicesModule) {
654	        this.microservicesModule = new msModule.MicroservicesModule();
655	        // Pre-cache the main barrel so connectMicroservice() can stay synchronous
656	        await loadPackage(
657	          '@nestjs/microservices',
658	          'NestFactory',
659	          () => import('@nestjs/microservices'),
660	        );
661	      }
662	    }
663	  }
664	}
