import {
  CallHandler,
  CanActivate,
  Controller,
  ExecutionContext,
  Get,
  INestApplication,
  Injectable,
  Module,
  NestInterceptor,
  Observable,
  PipeTransform,
  Query,
} from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import {
  FastifyAdapter,
  NestFastifyApplication,
} from '@nestjs/platform-fastify';
import * as http from 'http';
import { AppModule } from '../src/app.module.js';

interface RawResponse {
  status: number;
  headers: http.IncomingHttpHeaders;
  body: string;
}

const request = (
  port: number,
  path: string,
  agent?: http.Agent,
): Promise<RawResponse> =>
  new Promise<RawResponse>((resolve, reject) => {
    http
      .get(`http://localhost:${port}${path}`, { agent }, res => {
        let body = '';
        res.on('data', chunk => (body += chunk));
        res.on('end', () =>
          resolve({
            status: res.statusCode || 0,
            headers: res.headers,
            body,
          }),
        );
      })
      .on('error', reject);
  });

const counters = {
  guard: 0,
  pipe: 0,
  interceptor: 0,
  handler: 0,
};

@Injectable()
class CountingGuard implements CanActivate {
  canActivate() {
    counters.guard++;
    return true;
  }
